use std::{fs,path::Path};fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);let data=fs::read_to_string(p.join("CONTROL.tsv")).unwrap();let(mut classes,mut admitted,mut rejected,mut smooth,mut drop,mut repeated)=(0u64,0u64,0u64,0u64,0u64,0u64);let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='1050' height='520'><rect width='1050' height='520' fill='white'/><g font-family='Arial' fill='#183540'><text x='35' y='35' font-size='22'>Target-conditioned norm: exact residual comparisons</text><text x='35' y='63' font-size='14'>Every admitted residual equals direct Cantor. Attempted sign classes are not distinct relation ranks.</text>");
for(i,l)in data.lines().skip(1).enumerate(){let v:Vec<_>=l.split('\t').collect();let n=|j:usize|v[j].parse::<u64>().unwrap();classes+=n(4);admitted+=n(12);rejected+=n(4)-n(12);smooth+=n(13);drop+=n(15);repeated+=n(17);let x=70+i*160;let mut y=360.;for(c,col)in[(n(13),"#277f82"),(n(14),"#a4b7c2"),(n(4)-n(12),"#b56d38")]{let ht=c as f64/512.*240.;y-=ht;svg+=&format!("<rect x='{x}' y='{y:.2}' width='75' height='{ht:.2}' fill='{col}'/>");}svg+=&format!("<text x='{x}' y='{}' font-size='14'>{}/{}</text><text x='{x}' y='389' font-size='14'>g{} / t{}</text><text x='{x}' y='413' font-size='13'>p{} / {}</text>",y-10.,n(12),n(4),v[0],v[2],v[1],v[3]);}
for(i,(name,col))in[("split residual","#277f82"),("nonsplit residual","#a4b7c2"),("nonprimitive / rejected","#b56d38")].iter().enumerate(){let x=35+i*330;svg+=&format!("<rect x='{x}' y='443' width='17' height='17' fill='{col}'/><text x='{}' y='457' font-size='14'>{name}</text>",x+25);}svg+="<text x='35' y='493' font-size='13'>hec_target_rational_20261116 / frozen finite gate / exact counters; no wall timing or uncertainty estimate.</text></g></svg>";fs::write(p.join("COUNTS.svg"),svg).unwrap();let totals=format!("classes={classes}\nadmitted_exact_matches={admitted}\nrejected={rejected}\nsplit_group_checks={smooth}\ndegree_drops={drop}\nrepeated_target_admitted={repeated}\n");print!("{totals}");fs::write(p.join("TOTALS.txt"),totals).unwrap();}
